@import '../../utils/visually-hidden.css';

:host {
  display: block;
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
  overflow-x: auto;
  scrollbar-width: none;
}

:host::-webkit-scrollbar {
  display: none;
}

.pagination,
.pagination__page-size,
.pagination__navigation {
  display: flex;
  align-items: center;
  box-sizing: border-box;
}

.pagination {
  width: max-content;
  min-width: 100%;
  gap: var(--dimension-space-200);
}

.pagination__page-size,
.pagination__navigation {
  flex: 0 0 auto;
  gap: var(--dimension-space-050);
}

.pagination__range,
.pagination__page,
.pagination__label {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
  white-space: nowrap;
}

.pagination__page {
  justify-content: center;
  min-inline-size: calc(var(--dimension-size-800) + var(--dimension-space-200));
  padding-inline: var(--dimension-space-050);
}

import { Component, Event, EventEmitter, h, Host, Prop } from '@stencil/core';
import { resolvePaginationState } from './pagination-model';
import type { PaginationChangeDetail } from './pagination-types';

let paginationId = 0;

@Component({
  tag: 'ds-pagination',
  styleUrl: 'Pagination.css',
  scoped: true,
})
export class Pagination {
  /** Controlled zero-based page index. */
  @Prop() pageIndex: number = 0;
  /** Controlled number of top-level items on a full page. */
  @Prop() pageSize: number = 25;
  /** Controlled total number of top-level items across every page. */
  @Prop() totalItems: number = 0;
  /** Available page sizes. Assign arrays through JavaScript. */
  @Prop() pageSizeOptions: number[] = [25, 50, 100, 200];
  /** Localized plural noun used by assistive range announcements. */
  @Prop() itemLabel: string = 'items';
  /** Visible page-size control label. */
  @Prop() pageSizeLabel: string = 'Items per page';
  /** Accessible name for the pagination navigation region. */
  @Prop() label: string = 'Pagination';
  /** Prevent interaction while the owner replaces the current data page. */
  @Prop() loading: boolean = false;

  /** Emits the complete next controlled state after a page or page-size request. */
  @Event() dsChange!: EventEmitter<PaginationChangeDetail>;

  private readonly pageSizeControlId = `ds-pagination-${++paginationId}-page-size`;

  private requestPage(pageIndex: number): void {
    const state = this.resolvedState;
    if (this.loading || pageIndex === state.pageIndex || pageIndex < 0 || pageIndex >= state.totalPages) {
      return;
    }
    this.dsChange.emit({
      pageIndex,
      pageSize: state.pageSize,
      totalItems: state.totalItems,
      pageSizeOptions: state.pageSizeOptions,
      itemLabel: this.itemLabel,
      pageSizeLabel: this.pageSizeLabel,
      ariaLabel: this.label,
      previousPageIndex: state.pageIndex,
      previousPageSize: state.pageSize,
      reason: 'page',
    });
  }

  private requestPageSize(value: string | string[]): void {
    if (this.loading || typeof value !== 'string') return;
    const pageSize = Number(value);
    const state = this.resolvedState;
    if (!Number.isFinite(pageSize) || pageSize <= 0 || pageSize === state.pageSize) return;
    this.dsChange.emit({
      pageIndex: 0,
      pageSize: Math.trunc(pageSize),
      totalItems: state.totalItems,
      pageSizeOptions: state.pageSizeOptions,
      itemLabel: this.itemLabel,
      pageSizeLabel: this.pageSizeLabel,
      ariaLabel: this.label,
      previousPageIndex: state.pageIndex,
      previousPageSize: state.pageSize,
      reason: 'page-size',
    });
  }

  private get resolvedState() {
    return resolvePaginationState({
      pageIndex: this.pageIndex,
      pageSize: this.pageSize,
      totalItems: this.totalItems,
      pageSizeOptions: this.pageSizeOptions,
    });
  }

  render() {
    const state = this.resolvedState;
    const atStart = state.pageIndex === 0;
    const atEnd = state.pageIndex === state.totalPages - 1;
    const range = `${state.firstItem}–${state.lastItem} of ${state.totalItems}`;
    const page = `Page ${state.pageIndex + 1} of ${state.totalPages}`;

    return (
      <Host>
        <nav class="pagination" aria-label={this.label} aria-busy={this.loading ? 'true' : undefined}>
          <div class="pagination__page-size">
            <ds-text
              id={`${this.pageSizeControlId}-label`}
              class="pagination__label"
              as="span"
              variant="text-body-medium"
              color="secondary"
            >
              {this.pageSizeLabel}
            </ds-text>
            <ds-select
              size="md"
              inputId={this.pageSizeControlId}
              ariaLabelledby={`${this.pageSizeControlId}-label`}
              options={state.pageSizeOptions.map(value => ({ label: String(value), value: String(value) }))}
              value={String(state.pageSize)}
              allowClear={false}
              activeFill={false}
              isInactive={this.loading}
              onDsChange={event => {
                event.stopPropagation();
                this.requestPageSize(event.detail);
              }}
            />
          </div>
          <ds-text
            class="pagination__range"
            as="span"
            variant="text-body-medium"
            color="secondary"
            fontFeature="tabular-nums"
          >
            {range}
          </ds-text>
          <div class="pagination__navigation">
            <ds-button-unfilled
              variant="icon"
              size="md"
              icon="ChevronLeftDouble"
              ariaLabel="First page"
              hasBorder={false}
              isInactive={this.loading || atStart}
              onDsClick={() => this.requestPage(0)}
            />
            <ds-button-unfilled
              variant="icon"
              size="md"
              icon="ChevronLeft"
              ariaLabel="Previous page"
              hasBorder={false}
              isInactive={this.loading || atStart}
              onDsClick={() => this.requestPage(state.pageIndex - 1)}
            />
            <ds-text
              class="pagination__page"
              as="span"
              variant="text-body-medium"
              color="secondary"
              fontFeature="tabular-nums"
            >
              {page}
            </ds-text>
            <ds-button-unfilled
              variant="icon"
              size="md"
              icon="ChevronRight"
              ariaLabel="Next page"
              hasBorder={false}
              isInactive={this.loading || atEnd}
              onDsClick={() => this.requestPage(state.pageIndex + 1)}
            />
            <ds-button-unfilled
              variant="icon"
              size="md"
              icon="ChevronRightDouble"
              ariaLabel="Last page"
              hasBorder={false}
              isInactive={this.loading || atEnd}
              onDsClick={() => this.requestPage(state.totalPages - 1)}
            />
          </div>
          <span class="ds-visually-hidden" role="status" aria-live="polite" aria-atomic="true">
            {range} {this.itemLabel}. {page}.
          </span>
        </nav>
      </Host>
    );
  }
}

import type { PaginationState } from './pagination-types';

export const DEFAULT_PAGE_SIZE_OPTIONS = [25, 50, 100, 200] as const;

export interface ResolvedPaginationState {
  pageIndex: number;
  pageSize: number;
  totalItems: number;
  totalPages: number;
  firstItem: number;
  lastItem: number;
  pageSizeOptions: number[];
}

function nonNegativeInteger(value: number): number {
  return Number.isFinite(value) ? Math.max(0, Math.trunc(value)) : 0;
}

function positiveInteger(value: number, fallback: number): number {
  return Number.isFinite(value) && value > 0 ? Math.trunc(value) : fallback;
}

export function resolvePaginationState(
  state: Pick<PaginationState, 'pageIndex' | 'pageSize' | 'totalItems' | 'pageSizeOptions'>,
): ResolvedPaginationState {
  const pageSize = positiveInteger(state.pageSize, DEFAULT_PAGE_SIZE_OPTIONS[0]);
  const totalItems = nonNegativeInteger(state.totalItems);
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  const pageIndex = Math.min(nonNegativeInteger(state.pageIndex), totalPages - 1);
  const options = (state.pageSizeOptions?.length
    ? state.pageSizeOptions
    : DEFAULT_PAGE_SIZE_OPTIONS
  )
    .map(value => positiveInteger(value, 0))
    .filter(value => value > 0);
  const pageSizeOptions = [...new Set([...options, pageSize])].sort((left, right) => left - right);
  const firstItem = totalItems === 0 ? 0 : pageIndex * pageSize + 1;
  const lastItem = totalItems === 0 ? 0 : Math.min(totalItems, firstItem + pageSize - 1);

  return {
    pageIndex,
    pageSize,
    totalItems,
    totalPages,
    firstItem,
    lastItem,
    pageSizeOptions,
  };
}

export type PaginationChangeReason = 'page' | 'page-size';

/** Controlled pagination state shared by Pagination and pagination-aware consumers. */
export interface PaginationState {
  /** Zero-based page index. */
  pageIndex: number;
  /** Number of top-level items on a full page. */
  pageSize: number;
  /** Total number of top-level items across every page. */
  totalItems: number;
  /** Available page sizes. Defaults to 25, 50, 100, and 200. */
  pageSizeOptions?: number[];
  /** Localized plural noun used by assistive range announcements. */
  itemLabel?: string;
  /** Visible label for the page-size selector. */
  pageSizeLabel?: string;
  /** Accessible name for the pagination navigation region. */
  ariaLabel?: string;
}

/** Complete next controlled state emitted for a page or page-size request. */
export interface PaginationChangeDetail extends PaginationState {
  previousPageIndex: number;
  previousPageSize: number;
  reason: PaginationChangeReason;
}
